<div class="be_page"><div class="be_pagehead"><h1><?= e(t('wf.log')) ?> <span class="muted">#<?= (int)$sub['id'] ?></span></h1><a class="be_btn" href="<?= e(url('workflow', 'index', [$sub['id']])) ?>"><?= e(t('wf.back')) ?></a></div>
